def _signed32(value: int) -> int:
    value &= 0xFFFFFFFF
    return value if value < 0x80000000 else value - 0x100000000

def select_champion(available_mask: int, priorities: Sequence[int], tie_breaks: Sequence[int]) -> int:
    """Native 433370/433A50: highest signed priority, lowest unsigned tie.

    Ascending index iteration preserves the lowest handle for a complete tie.
    No available champion returns the native sentinel 0xFF.
    """
    selected = 0xFF
    remaining = available_mask & 0xFFFF
    while remaining:
        bit = remaining & -remaining
        index = bit.bit_length() - 1
        remaining ^= bit
        if (selected == 0xFF or
            _signed32(priorities[index]) > _signed32(priorities[selected]) or
            (_signed32(priorities[index]) == _signed32(priorities[selected]) and
             (tie_breaks[index] & 0xFFFFFFFF) < (tie_breaks[selected] & 0xFFFFFFFF))):
            selected = index
    return selected

def next_team_after_turn(
    team: int, team_counts: Sequence[int], team_masks: Sequence[int],
) -> tuple[int | None, tuple[int, int]]:
    """Native 433370 increments a team's count then alternates if possible.

    None means both teams exhausted their roster-sized number of turns.
    Roster count deliberately uses team masks without intersecting alive masks.
    """
    counts = [team_counts[0] & 0xFF, team_counts[1] & 0xFF]
    counts[team] = (counts[team] + 1) & 0xFF
    capacities = [(team_masks[0] & 0xFFFF).bit_count(),
                  (team_masks[1] & 0xFFFF).bit_count()]
    if counts[0] >= capacities[0] and counts[1] >= capacities[1]:
        return None, (counts[0], counts[1])
    other = team ^ 1
    next_team = other if counts[other] < capacities[other] else team
    return next_team, (counts[0], counts[1])
